function extract($, ctx) {
  const items = [];
  const seen = new Set();

  $('section.elementor-section').each((_, sec) => {
    const $sec = $(sec);
    // Section heading (h2 with the elementor heading title)
    const $heading = $sec.find('h2.elementor-heading-title');
    const section = $heading.length ? cleanText($heading.text()) : null;

    // Price list for this section
    const $priceList = $sec.find('ul.elementor-price-list');
    if (!$priceList.length) return;

    $priceList.find('li.elementor-price-list-item').each((_, li) => {
      const $li = $(li);

      // Dish name
      const nameRaw = $li.find('span.elementor-price-list-title').text();
      const name = cleanText(nameRaw);
      if (!name) return;

      // Description (may be missing)
      const descRaw = $li.find('p.elementor-price-list-description').text();
      const description = descRaw ? cleanText(descRaw) : null;

      // Price
      const priceRaw = $li.find('span.elementor-price-list-price').text();
      const price = parsePrice(priceRaw);

      // Dedup exact repeats (same section, name, price)
      const key = `${section || ''}|${name}|${price ?? ''}`;
      if (seen.has(key)) return;
      seen.add(key);

      items.push({ section, name, description, price });
    });
  });

  return items;
}
